"""
O552: a self-invoice and a payment voucher keep the plant's GSTIN and letterhead as they were issued, where the
printout read GstSettings.active() and the company as they stood on the day it was printed.

Documents issued before this migration kept nothing, and what they printed when issued is not recorded anywhere:
they are filled from the settings as they stand on the day this migration runs (the active GST registration's
GSTIN, the company's name, legal name, address and tax id), which is what they printed until now. From here on
each keeps what it was issued with, and a later change of either no longer reprints it.
"""

from django.db import migrations, models


def _letterhead(company):
    # core.documents.issuer, against the historical models (Address.formatted is not on them).
    if company is None:
        return {"name": "", "legal_name": "", "address": [], "tax_id": ""}
    address = []
    if company.address_id:
        where = company.address
        address = [where.line1] + ([where.line2] if where.line2 else [])
        city = " ".join(part for part in [where.city, where.state, where.postal_code] if part)
        if city:
            address.append(city)
        if where.country_id:
            address.append(where.country.name)
    return {"name": company.name, "legal_name": company.legal_name or "", "address": address,
            "tax_id": company.tax_id or ""}


def fill_from_todays_settings(apps, schema_editor):
    registration = apps.get_model("accounting", "GstSettings").objects.filter(is_active=True).first()
    company = apps.get_model("core", "Company").objects.first()
    kept = {"recipient_gstin": registration.gstin if registration else "", "letterhead": _letterhead(company)}
    for name in ("SelfInvoice", "PaymentVoucher"):
        apps.get_model("gst", name).objects.all().update(**kept)


